#include "irr_physics_pipeline.hpp"
#include "irr_bulk.hpp"
using irr::require;
int_t factor_norm(const irr::matrices& blocks,int_t& den){den=1;for(const auto& b:blocks)for(const auto& r:b.rows)for(auto [c,x]:r)den=LCM(den,x.den());int_t sum=0;for(const auto& b:blocks)for(const auto& r:b.rows)for(auto [c,x]:r){int_t v=den;v/=x.den();v*=x.num().abs();sum+=v;}return sum;}
int main(int argc,char**argv)try{
 require(argc==8,"physical_seam_certificate H K UNIQUE BULK FEC LEC DATA");size_t h=std::stoul(argv[1]),k=std::stoul(argv[2]);fs::path root=fs::absolute(argv[3]),bulk=fs::canonical(argv[4]),fec=argv[5],lec=argv[6],data=argv[7];
 Flint::set_memory_functions();rref_option_t opt;opt->pool.reset(2);auto* pool=&opt->pool;irr_stage::verify_complete(root);auto object=irr_io::read_object(root,h,k,fec,lec,pool);require(object.kind=="unique"&&object.directions==0,"Need a unique QQ object");
 // This certificate relies on the separately certified complete QQ bulk and
 // the declared affine lineage. Every child is an affine combination of it.
 auto current=root;size_t depth=0;while(fs::weakly_canonical(current)!=bulk){require(++depth<64,"Cyclic or missing physical ancestry");auto recipe=irr_stage::read(current/"stage.tsv");require(recipe.at("h")==std::to_string(h)&&recipe.at("k")==std::to_string(k),"Physical split changed");require(recipe.at("operator")=="collinear"||recipe.at("operator")=="mrk"||recipe.at("operator")=="ope_small_s","Unexpected physical operator");current=fs::weakly_canonical(current/recipe.at("parent"));}
 irr_run::verify_checksums(bulk);irr_stage::verify_basis(root,irr_stage::basis_identity(fec,lec,h,k),h,k);

 std::set<std::string> identities;{std::ifstream in(bulk/"inputs.sha256");std::string line;while(std::getline(in,line)){std::istringstream record(line);std::string hash;record>>hash;identities.insert(hash);}}
 for(const auto& file:{data/"dlogmat_full_ca_pd3.wxf",data/"dlogmat_full_ca_pd3_blocks.tsv"})require(identities.count(hex_sha256_file(file)),"Physical certificate condition differs from certified bulk");
 irr::channels_t cg(pool);auto mf=irr_bulk::read_copies(fec,h,true),ml=irr_bulk::read_copies(lec,k,false),of=irr_bulk::read_copies(fec,h-1,true),ol=irr_bulk::read_copies(lec,k-1,false);std::ofstream discard("/dev/null");auto first=irr_bulk::read_chain(fec,h,true,mf,discard,pool),last=irr_bulk::read_chain(lec,k,false,ml,discard,pool);
 auto W=irr::read_tensor(data/"dlogmat_full_ca_pd3.wxf",pool);auto t=irr::make_seam_template(cg,W,nmhv_sew_read_irrep_axis(data/"dlogmat_full_ca_pd3_blocks.tsv"),opt);auto layout=irr::seam_layout(t,of,ol,mf,ml);
 int_t df,dl,dr=1,dc=1,sr=0;auto sf=factor_norm(first,df),sl=factor_norm(last,dl);for(const auto& b:t.routes)for(const auto& l:b)for(const auto& r:l)for(const auto& v:r)dr=LCM(dr,v.value.den());for(const auto& b:t.routes)for(const auto& l:b)for(const auto& r:l)for(const auto& v:r){int_t x=dr;x/=v.value.den();x*=v.value.num().abs();sr+=x;}
 std::vector<rat_t> C(layout.columns);size_t offset=0;for(const auto& b:object.S){for(auto [j,x]:b[0]){C[offset+j]=x;dc=LCM(dc,x.den());}offset+=b.ncol;}require(offset==layout.columns,"Unique sewing dimensions");int_t maximum=0;for(const auto& x:C){int_t v=dc;v/=x.den();v*=x.num().abs();maximum=std::max(maximum,v);}int_t bound=sf*sl*sr*maximum,modulus=1;size_t count=0;
 for(const auto& file:fs::directory_iterator(root/"cache")){auto name=file.path().filename().string();if(file.path().extension()!=".bin"||name.size()<6||name[0]!='p')continue;ulong p=std::stoull(name.substr(1,name.size()-5));field_t F(FIELD_Fp,p);require(df%F.mod!=0&&dl%F.mod!=0&&dr%F.mod!=0&&dc%F.mod!=0,"Bad physical certificate prime");auto K=read_cache(root,p,h,k);require(K.nrow==1&&K.ncol==C.size(),"Unique cache dimensions");std::vector<ulong> row(C.size());for(auto [j,x]:K[0])row[j]=x;for(size_t j=0;j<C.size();++j)require(C[j]%F.mod==row[j],"Unique QQ/cache congruence mismatch");modulus*=p;++count;}
 require(count>0&&bound<modulus,"Original seam height bound needs more physical primes");std::cout<<"PHYSICAL_SEAM_CERTIFICATE {\"exact_original_interface\":true,\"original_rows\":"<<layout.rows<<",\"invariant_columns\":"<<layout.columns<<",\"complete_primes\":"<<count<<",\"bound_bits\":"<<bound.bits()<<",\"modulus_bits\":"<<modulus.bits()<<",\"bulk_lineage_verified\":true}"<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}
